    if (a[kind]) return { pulse: a[kind][0], step: a[kind][1] };
    const compact = String(modeLabel || mode || "mode").replace(/\s*\/\s*/g, "/").slice(0, 18);
    return { pulse: `Show ${compact}`, step: `Advance ${compact}` };
