      const projectionFoot = addSphereVisual(group, [origin[0] + 0.8, origin[1], origin[2] + 0.4], 0.075, PALETTE.violet, 0.36);
      projectionFoot.userData.vectorArtifact = "projection-foot";
      track(projectionFoot, "projection foot on subspace");
      const residualSegment = addBeamVisual(group, [origin[0] + 0.8, origin[1], origin[2] + 0.4], [origin[0] + 0.8, origin[1] + 0.75, origin[2] + 0.4], PALETTE.rose, 0.24, 0.018);
      residualSegment.userData.vectorArtifact = "orthogonal-residual";
