      track(addRingVisual(group, [basisOrigin[0], basisOrigin[1], basisOrigin[2]], 0.18, PALETTE.cyan, 0.26), "basis origin anchor");
      addVisualLabel(group, "basis e1,e2", [stages[0], -0.62, 0.82], "#dbeafe", [0.58, 0.18, 1]);

      trackMany(addMatrixPanel(group, [stages[1], -1.47, 0.0], 2, 2, 0.46, [PALETTE.green, PALETTE.amber, PALETTE.blue], 0.22, "matrix A panel"), "matrix A panel");
      addVisualLabel(group, "matrix A", [stages[1], -0.63, 0.88], "#e8b857", [0.52, 0.17, 1]);
      track(addArrowVisual(group, [stages[0] + 0.42, -1.42, -0.05], [stages[1] - 0.35, -1.42, -0.05], PALETTE.amber, 0.2), "basis enters matrix");
      track(addArrowVisual(group, [stages[1] + 0.34, -1.42, -0.05], [stages[2] - 0.7, -1.42, -0.05], PALETTE.green, 0.22), "matrix transforms basis");

      const gridOrigin = [stages[2] - 0.46, -1.88, -0.36];
      const ae1 = [stages[2] + 0.72, -1.58, -0.2];
