      track(addTriangleVisual(group, [ae1, ae12, ae2], PALETTE.green, 0.1), "determinant area image grid");
      [[gridOrigin, ae1], [gridOrigin, ae2], [ae1, ae12], [ae2, ae12]].forEach(([a, b]) => {
        track(addBeamVisual(group, a, b, PALETTE.cyan, 0.25, 0.018), "image grid span boundary");
      });
      for (let i = -2; i <= 2; i += 1) {
        const t = i * 0.22;
        track(addBeamVisual(group, [gridOrigin[0] + t, -2.02, gridOrigin[2] - 0.3], [ae1[0] + t, -1.72, ae1[2] - 0.3], PALETTE.blue, 0.08, 0.008), "visible direction image grid");
        track(addBeamVisual(group, [gridOrigin[0] - 0.3, -1.98, gridOrigin[2] + t], [ae2[0] - 0.3, -0.92, ae2[2] + t], PALETTE.blue, 0.08, 0.008), "visible direction image grid");
      }
      track(addBlockVisual(group, [stages[2], -0.6, 0.34], [0.9, 0.07, 0.18], PALETTE.green, 0.2), "determinant area scale");
      addVisualLabel(group, "image grid", [stages[2], -0.45, 0.92], "#58e0d3", [0.52, 0.17, 1]);

      track(addBlockVisual(group, [stages[3], -1.42, 0.02], [1.18, 0.07, 0.18], PALETTE.green, 0.24), "span column space rank");
      track(addRingVisual(group, [stages[3] + 0.2, -1.42, 0.02], 0.46, PALETTE.green, 0.18), "rank signal surviving directions");
      track(addBeamVisual(group, [stages[3] - 0.54, -1.9, -0.42], [stages[3] + 0.66, -0.92, 0.46], PALETTE.rose, 0.27, 0.019), "nullspace direction defect");
      track(addBlockVisual(group, [stages[3] + 0.6, -0.74, 0.54], [0.08, 0.46, 0.16], PALETTE.rose, 0.18), "rank collapse defect");
      addVisualLabel(group, "rank/nullspace", [stages[3], -0.45, 0.94], "#77df96", [0.62, 0.18, 1]);

      const projBase = [stages[4] - 0.48, -1.88, -0.36];
      const projPoint = [stages[4] + 0.38, -1.04, 0.18];
      const target = [stages[4] + 0.72, -0.56, 0.82];
      track(addBeamVisual(group, [stages[4] - 0.68, -1.92, -0.42], [stages[4] + 0.78, -1.04, 0.18], PALETTE.green, 0.22, 0.018), "projection subspace span");
      track(addArrowVisual(group, projBase, target, PALETTE.cyan, 0.28), "target vector y");
