      addVisualLabel(group, "1", [stageX[0] - 0.64, -0.34, 0.36], "#58e0d3", [0.42, 0.42, 1]);
      addVisualLabel(group, "local values x_v", [stageX[0], -0.34, 0.36], "#58e0d3", [1.2, 0.32, 1]);
      addVisualLabel(group, "one vector per node stalk", [stageX[0], -0.68, 0.36], "#9cb4b0", [1.05, 0.24, 1]);

      const edgePlate = [stageX[1], -1.42, 0.12];
      track(addBlockVisual(group, edgePlate, [0.92, 0.09, 0.52], PALETTE.amber, 0.3), "single edge-stalk comparison plate");
      track(addBeamVisual(group, [stageX[0] - 0.12, -1.12, 0.05], edgePlate, PALETTE.blue, 0.28, 0.022), "restriction map F_u->e");
      track(addBeamVisual(group, [stageX[0] + 0.28, -1.0, 0.05], edgePlate, PALETTE.amber, 0.28, 0.022), "restriction map F_v->e");
      addVisualLabel(group, "2", [stageX[1] - 0.64, -0.34, 0.42], "#e8b857", [0.42, 0.42, 1]);
      addVisualLabel(group, "restrict with F", [stageX[1], -0.34, 0.42], "#e8b857", [1.16, 0.32, 1]);
      addVisualLabel(group, "compare inside edge stalk", [stageX[1], -0.68, 0.42], "#9cb4b0", [1.18, 0.24, 1]);

      track(addBlockVisual(group, [stageX[2] - 0.18, -1.45, 0.1], [0.18, 1.15, 0.22], PALETTE.cyan, 0.28), "projected endpoint value");
      track(addBlockVisual(group, [stageX[2] + 0.18, -1.45, 0.1], [0.18, 0.64, 0.22], PALETTE.amber, 0.28), "projected endpoint value");
      track(addBeamVisual(group, [stageX[2] - 0.18, -0.84, 0.1], [stageX[2] + 0.18, -1.1, 0.1], PALETTE.rose, 0.42, 0.045), "delta x residual rod");
      track(addRingVisual(group, [stageX[2], -1.08, 0.1], 0.48, PALETTE.rose, 0.3), "mismatch residual highlight");
      addVisualLabel(group, "3", [stageX[2] - 0.58, -0.34, 0.42], "#ff6d8b", [0.42, 0.42, 1]);
      addVisualLabel(group, "residual delta x", [stageX[2], -0.34, 0.42], "#ff6d8b", [1.18, 0.32, 1]);
      addVisualLabel(group, "zero iff restrictions agree", [stageX[2], -0.68, 0.42], "#9cb4b0", [1.18, 0.24, 1]);

      trackMany(addMatrixPanel(group, [stageX[3], -1.52, 0.06], 4, 4, 0.3, [PALETTE.cyan, PALETTE.blue, PALETTE.violet], 0.18, "Laplacian block matrix"), "Laplacian block matrix");
      addVisualLabel(group, "4", [stageX[3] - 0.58, -0.34, 0.42], "#58e0d3", [0.42, 0.42, 1]);
      addVisualLabel(group, "L_F = delta^T delta", [stageX[3], -0.34, 0.42], "#58e0d3", [1.32, 0.32, 1]);
      addVisualLabel(group, "sends residual force back", [stageX[3], -0.68, 0.42], "#9cb4b0", [1.15, 0.24, 1]);

      const h05BowlCenter = [stageX[4], -1.52, 0.06];
      track(addRingVisual(group, h05BowlCenter, 0.78, PALETTE.amber, 0.28), "Dirichlet energy bowl");
      track(addRingVisual(group, h05BowlCenter, 0.48, PALETTE.cyan, 0.22), "Dirichlet energy level set");
      track(addRingVisual(group, h05BowlCenter, 0.2, PALETTE.green, 0.3), "kernel harmonic anchor");
      addArrowVisual(group, [stageX[4] - 0.52, -1.28, -0.08], [stageX[4] - 0.08, -1.48, 0.02], PALETTE.green, 0.24);
      addArrowVisual(group, [stageX[4] + 0.52, -1.28, -0.08], [stageX[4] + 0.08, -1.48, 0.02], PALETTE.green, 0.24);
      addVisualLabel(group, "5", [stageX[4] - 0.58, -0.34, 0.42], "#77df96", [0.42, 0.42, 1]);
      addVisualLabel(group, "energy -> kernel", [stageX[4], -0.34, 0.42], "#77df96", [1.18, 0.32, 1]);
