      points.forEach((p, i) => track(addSphereVisual(group, p, 0.13, i === 4 ? PALETTE.rose : PALETTE.blue, 0.34), "filtration point"));
      track(addRingVisual(group, [0, -1.45, 0.35], 0.85, PALETTE.blue, 0.16), "filtration radius");
      track(addRingVisual(group, [0, -1.45, 0.35], 1.55, PALETTE.cyan, 0.14), "filtration radius");
      track(addRingVisual(group, [0, -1.45, 0.35], 2.35, PALETTE.amber, 0.12), "filtration radius");
      [[0, 1], [1, 2], [2, 0], [2, 3], [1, 4]].forEach(([a, b], i) => track(addBeamVisual(group, points[a], points[b], i === 4 ? PALETTE.rose : PALETTE.cyan, 0.2, 0.014), "cell birth edge"));
