      "stochastic-calculus-lab": ["Brownian scaling", "Quadratic variation", "Ito integral", "SDE step", "Ito lemma", "Reverse diffusion", "alias:Brownian path", "alias:quadratic variation", "alias:Ito integral", "alias:drift field", "alias:SDE solution"],
      "information-geometry-lab": ["Statistical manifold", "Fisher metric", "KL microscope", "Reparameterization", "Natural gradient", "Projections/priors", "alias:statistical manifold", "alias:Fisher metric", "alias:KL neighborhood", "alias:geodesic", "alias:natural gradient"],
